sys_variable_value.value:
/**
 * Creates the bfd_case_metric_snapshot row on closure: metric_date = today,
 * case_type, team = assigned_team, age_hours, sla_status, recovery_amount,
 * resolution_time_hours and csat_score.
 */
(function execute(inputs, outputs) {
    outputs.snapshot = new bfd_FlowSupport().createMetricSnapshot(inputs.caseSysId);
})(inputs, outputs);

